from docx import Document
from pathlib import Path
from copy import deepcopy
f=Path('Отчет_Хаялиев_ИУ6-74Б_Генерация_описаний_Авито.docx');d=Document(f)
r={
6:'Базовая VLM прошла проверку формата в 86 случаях из 100, SFT VLM — в 18, CLIP с ruGPT — ни в одном. Эти результаты характеризуют соблюдение формальных ограничений и дополняют содержательную оценку генераций. Решение пригодно для демонстрации и дальнейших исследований. Промышленное внедрение требует согласования протокола оценки и проверки на расширенной выборке.',
63:'Исходные данные представлены подготовленными таблицами объявлений Авито [1]. Работа с данными включает проверку структуры, разделения выборок и распределения категорий. Программная часть объединяет обучение и применение генераторов [2] с модулем LLM-as-a-Judge [3]. Обоснование пользовательского сценария и ожидаемого эффекта определяет требования к прототипу [4].',
64:'Работа выполнена в рамках совместного проекта с Даниилом Ханенко. Разработка объединяет исследование моделей, реализацию пользовательского сценария и экспериментальную оценку. Основное внимание уделено достоверности описаний, соблюдению заданного формата и возможности запуска системы на ограниченных вычислительных ресурсах.',
87:'Компания Авито предоставляет данные в пригодном для обработки формате. Рабочий вход представляет собой готовую таблицу объявлений, связанную с изображениями через image_id. Перед использованием проверяются обязательные поля, корректность JSON-параметров и принадлежность объектов обучающей или проверочной выборке.',
91:'Табличный контракт используется как при обучении, так и при оценке генераторов. Изображение загружается по соответствующему идентификатору, а характеристики передаются в текстовую часть запроса. Раздельная проверка таблиц и изображений позволяет выявлять ошибки входа до обращения к модели и сохранять соответствие ответа исходному объекту.',
94:'Таблица 3 — Результат проверки выборок',
97:'Для более строгого контроля требуется поиск дубликатов изображений и близких описаний, а также группировка по продавцам. Два объявления одного продавца могут использовать общий рекламный шаблон и создавать зависимость между обучением и проверкой. Дополнительно необходимо выделить независимый тестовый набор для окончательной оценки выбранной конфигурации.',
107:'Подготовка исходных данных включает фильтры наличия фотографии и описания, длины текста, положительной цены, отсутствия контактов, уникальности, времени размещения и товарной категории. Для отбора используется quality_score, учитывающий свойства текста, продавца и объявления. Генераторы работают с результатом этой подготовки — готовыми выборками объявлений [1, 2].',
108:'В работе используются обучающая выборка из 30 000 записей, проверочная из 100 записей и дополнительная из 2 937 записей. Их размеры характеризуют отдельные наборы данных. Обучающая выборка предназначена для настройки модели, проверочная — для сопоставления ответов генераторов. Дополнительный набор позволяет исследовать структуру признаков и свойства описаний.',
109:'Дополнительные характеристики извлекались из исходных описаний моделью Meta-Llama-3.3-70B с проверкой ответа и повторными попытками. Для животных применялся отдельный промпт. Такой способ позволяет получить согласованный JSON, но создает важную особенность постановки: часть сведений из целевого текста становится входом генератора.',
116:'Схема генерации по изображению и характеристикам показана на рисунке 2. Она допускает расширение входа до нескольких фотографий. В реализованном сервисе запрос содержит одно изображение: это уменьшает требования к памяти и упрощает обработку. Текстовые характеристики дополняют визуальные признаки сведениями, которые невозможно надежно определить по фотографии [2, 4].',
118:'Рисунок 2 — Схема генерации описания по изображению и характеристикам',
132:'В мультимодальной ветви используется Qwen3-VL с LoRA-контрольной точкой ckpt-step-3000. При инференсе получены 100 непустых ответов без ошибок генерации. Адаптер изменяет поведение базовой модели без замены всего набора весов. Настройки текстовой и мультимодальной ветвей рассматриваются раздельно, поскольку состав входа и обработка визуальных токенов различаются.',
137:'При генерации декодер последовательно предсказывает токены, учитывая текстовый контекст и представление изображения. Проекция enc_to_dec_proj согласует размерности скрытых представлений. Энкодер CLIP заморожен, тогда как декодер и добавленные компоненты остаются обучаемыми. Всего имеется около 1 152,8 млн параметров, из них обучаемых — 1 065,4 млн.',
144:'Выбор базовой VLM для MVP обоснован простотой развертывания, наличием штатного мультимодального интерфейса и лучшим соблюдением формальных правил среди проверенных генераторов. Содержательный балл SFT VLM при этом выше. Для пользовательского сервиса важны оба свойства: полнота описания и возможность получить результат в заданном кратком формате.',
165:'Frontend реализован на React и TypeScript. Пользователь выбирает или перетаскивает изображение, заполняет заголовок, категорию и JSON-параметры. Состояние формы включает готовность runtime, ход запроса, текст результата и ошибку. Интерфейс генератора описаний показан на рисунке 3.',
167:'Рисунок 3 — Интерфейс генератора описаний',
175:'Проверка Python-компонентов через unittest охватывает 24 теста: 21 выполнен успешно, три API-теста пропущены из-за отсутствующих тестовых зависимостей FastAPI. Результат подтверждает поведение охваченных функций. Проверки frontend и сквозного сценария с GPU следует учитывать отдельно: успешные модульные тесты не гарантируют корректность всех взаимодействий сервиса.',
190:'Содержательное сравнение допускает некоторые приветствия и оценочные слова без штрафа. Строгий валидатор запрещает приветствия и проверяет ограничения формата. Поэтому средний балл качества и доля прохождения ad_validator отражают разные свойства генератора. При интерпретации результатов необходимо учитывать примененную рубрику и условия допуска ответа к судейству.',
191:'В CSV для CLIP с ruGPT колонка результата называется pred_description, а список автоматически распознаваемых колонок judge этого имени не содержит. При неосторожном запуске может быть выбран description, то есть исходный текст продавца. Для проверки ответов генератора колонка pred_description передается валидатору явно. Соответствие колонок моделям необходимо задавать до расчета метрик.',
192:'Содержательные и формальные показатели рассчитываются раздельно. Средний балл отражает оценку полезности и качества текста, а программная проверка — выполнение обязательных правил. Объединять их в одну шкалу без заданной процедуры нельзя. Для выбора модели результаты сопоставляются с требованиями пользовательского сценария: ответ должен быть информативным и пригодным для вставки в объявление.',
194:'5.3 Сравнение качества генерации',
195:'Средние содержательные оценки пяти вариантов генератора приведены в таблице 6. Сравнение охватывает текстовую модель, ее дообученную версию, CLIP с ruGPT, базовую и дообученную VLM. Такой состав позволяет отдельно рассмотреть влияние визуального входа и адаптации модели к описаниям товарных объявлений.',
196:'Таблица 6 — Средние содержательные оценки генераторов',
198:'Прирост после дообучения может быть связан с усвоением предметной лексики и более полным использованием характеристик. Вместе с тем модель воспроизводит стиль обучающих целей, включая длинные перечисления и рекламные обороты. Поэтому повышение содержательной оценки не гарантирует соблюдения ограничений интерфейса и требует отдельного анализа структуры ответа.',
199:'Мультимодальное дообучение показывает потенциал по содержательной оценке. Для устойчивого ранжирования необходимо повторить сравнение с одинаковыми условиями генерации и единой рубрикой. Причины изменения отдельных свойств текста следует проверять на уровне примеров: выделять добавленные факты, пропуски характеристик и нарушения формата.',
214:'Главные ограничения оценки — малый размер valid, отсутствие одной из категорий и неодинаковые конфигурации генераторов. Для проверки фактической точности требуется ручная разметка утверждений с привязкой к полю или фрагменту изображения. Дополнительно необходимо оценить согласованность судей. Формальные и модельные оценки остаются взаимодополняющими, но неполными измерениями.',
217:'Нагрузочные испытания демонстрационного сервиса характеризуют задержку ответа, пропускную способность и потребление ресурсов. Результаты приведены в таблице 8. Измерения относятся к конфигурации с NVIDIA RTX 3060 и позволяют определить рабочий диапазон параллельных запросов для MVP. Перенос результатов на другое оборудование требует отдельной проверки.',
218:'Таблица 8 — Характеристики сервиса при нагрузочном тестировании',
224:'Для пользовательского эксперимента вводятся две отдельные метрики: Acceptance Rate — доля использованных генераций, Edit Rate — доля ответов, которые продавец изменил. Рост первой метрики обычно желателен, а смысл второй зависит от величины и причины правок. Исправление фактической ошибки необходимо отличать от изменения стиля по предпочтению продавца.',
225:'Экономический эффект можно оценить сценарным расчетом. При условных 10 млн случаев, конверсии 5 %, чеке 5 000 руб. и относительном приросте 1,7 % получается 42,5 млн руб. дополнительного оборота за период. Эта величина иллюстрирует зависимость эффекта от исходных допущений. Она не является выручкой платформы или измеренным результатом MVP: доля платформы и затраты не заданы.',
227:'Одно из направлений развития — объединение отдельных визуальных ветвей с помощью адаптеров. Вариант архитектуры показан на рисунке 5. Его исследовательская задача состоит в сопоставлении разных представлений изображения и оценке их вклада в полноту описания. Реализованный MVP использует Qwen-VLM; расширенная схема требует самостоятельного эксперимента.',
230:'Рисунок 5 — Вариант архитектуры с двумя визуальными энкодерами',
238:'Исследовательская часть охватывает текстовые и мультимодальные модели до и после SFT, а также CLIP с ruGPT и cross-attention. Наибольшая средняя содержательная оценка составляет 0,78 для SFT VLM. Этот результат указывает на перспективность адаптации модели к задаче, однако выбор конфигурации сервиса требует также учитывать формат, задержку и достоверность отдельных утверждений.',
240:'Основная цель — построение прототипа и исследование вариантов генерации — достигнута. Реализован полный пользовательский путь от загрузки фотографии и характеристик до получения черновика описания. Промышленная интеграция и пользовательский A/B-тест относятся к следующим этапам развития. Перед внедрением требуется расширить проверку качества и устойчивости системы.',
243:'1. Авито. Набор данных товарных объявлений для задачи генерации описаний : обучающая, проверочная и дополнительная выборки. — Данные проекта. — Формат: CSV, изображения.',
262:'При повторной проверке правил следует использовать одинаковую версию ad_validator для всех вариантов. Полный прогон судей дополнительно требует фотографий, настроенного доступа к моделям и фиксированной рубрики. Результаты необходимо сохранять с идентификаторами объектов и названиями конфигураций, чтобы сопоставлять оценки одного объявления между генераторами.'
}
for i,t in r.items():
 p=d.paragraphs[i]; prop=deepcopy(p.runs[0]._r.rPr) if p.runs and p.runs[0]._r.rPr is not None else None
 p.clear();run=p.add_run(t)
 if prop is not None:run._r.insert(0,prop)
for p in d.paragraphs:
 for run in p.runs:
  run.text=run.text.replace('5.3 Сравнение подходов по материалам проекта','5.3 Сравнение качества генерации')
assert not any('презентац' in p.text.lower() or 'слайд' in p.text.lower() for p in d.paragraphs)
d.save(f)
print('Rewritten paragraphs:',len(r))
